def missing_inputs(a: "Analysis", r: Release) -> list[str]:
    """Fields an analysis needs that this release doesn't have, e.g. 'protein_rppa.tsv.gz: ERALPHA'."""
    out = []
    for name, need in a.fields.items():
        if not need or not r.has(name):
            continue
        have = set(r.clinical.columns) if name == "clinical.tsv" else set(r.table(name).index)
        out += [f"{name}: {f}" for f in sorted(set(need) - have)]
    return out

def release_verdict(affected: bool, movement: Movement | None, inputs=None) -> AnalysisVerdict:
    """movement is None when the analysis wasn't rerun. inputs: a SliceDiff of exactly what it reads, if computed."""
    if movement is None:
        return AnalysisVerdict("Ready", "Nothing this analysis uses changed; not rerun.")
    if not affected:
        if movement.moved:
            return AnalysisVerdict("Blocked", "The result moved although no detected change touches this "
                                   f"analysis: something changed that the detector didn't report ({movement.magnitude}).")
        if inputs is not None and inputs.any:
            return AnalysisVerdict("Conditional", "Data this analysis reads changed with no detected change to explain it, "
                                   f"though the result didn't move ({movement.magnitude}).")
        same = f"the {inputs.identical} samples it reads are identical in both releases; " if inputs is not None else ""
        return AnalysisVerdict("Ready", f"Nothing this analysis uses changed: {same}a check rerun confirms it ({movement.magnitude}).")
    if movement.insufficient:
        return AnalysisVerdict("Insufficient Evidence", f"Too few samples left in a group after the change ({movement.magnitude}).")
    if movement.flipped:
        return AnalysisVerdict("Blocked", f"The conclusion flipped ({movement.magnitude}).")
    if movement.beyond_tolerance:
        return AnalysisVerdict("Blocked", f"The result moved beyond tolerance ({movement.magnitude}).")
    if movement.moved:
        return AnalysisVerdict("Conditional", f"Inputs changed; the result moved within tolerance ({movement.magnitude}).")
    return AnalysisVerdict("Conditional", f"Inputs changed but the result did not move ({movement.magnitude}).")

def touches(ch: Change, a: Analysis, eligible: set[str]) -> tuple[bool, str]:
    if ch.file not in a.files:
        return False, f"in a file it doesn't read ({ch.file})"
    used = a.fields.get(ch.file, set())  # None = reads every row of that file
    if ch.fields and used is not None and not (set(ch.fields) & used):
        return False, f"change fields it doesn't use ({ch.file}: {', '.join(sorted(ch.fields))[:80]})"
    if not (_ids(ch) & eligible):
        return False, "are samples outside its cohort"
    return True, ""


def _eligible(a: Analysis, r: Release) -> set[str]:
    """The analysis cohort in one release, or empty when that release lacks its inputs. A missing file or field
    is reported later as Insufficient Evidence with the reason (findings.build); it must not crash the map."""
    if not all(r.has(f) for f in a.files):
        return set()
    try:
        return a.eligible(r)
    except (KeyError, ValueError, OSError):
        return set()

def map_impact(changes: list[Change], release_a: Release, release_b: Release,
               analyses: list[Analysis] = ANALYSES) -> dict[str, Impact]:
    out = {}
    for a in analyses:
        eligible = _eligible(a, release_a) | _eligible(a, release_b)
        imp = Impact(a)
        for i, ch in enumerate(changes):
            hit, reason = touches(ch, a, eligible)
            if hit:
                imp.touched_by.append(i)
            else:
                imp.skipped[reason] += 1
        out[a.id] = imp
    return out

def a1_run(r: Release) -> dict:
    er = _clinical(r).set_index("sampleID")[ER_COL]
    samples = [s for s in r.protein.columns if is_primary(s) and er.get(s) in ("Positive", "Negative")]
    vals = r.protein.loc["ERALPHA", samples]
    pos = vals[[s for s in samples if er[s] == "Positive"]]
    neg = vals[[s for s in samples if er[s] == "Negative"]]
    mp, mn = float(pos.mean()), float(neg.mean())
    return {"n_samples": len(samples), "n_positive": int(pos.size), "n_negative": int(neg.size),
            "mean_positive": round(mp, 3), "mean_negative": round(mn, 3), "difference": round(mp - mn, 3),
            "sample_ids": sorted(samples)}


def a1_slice(r: Release) -> dict[str, tuple]:
    er = _clinical(r).set_index("sampleID")[ER_COL]
    row = r.protein.loc["ERALPHA"]
    out = {}
    for s in r.protein.columns:
        if is_primary(s) and er.get(s) in ("Positive", "Negative"):
            v = float(row[s])
            out[s] = ((er[s], repr(v)), f"ER {er[s]}, ERALPHA {v:.3f}")

DECISIONS = ("approve", "reject", "request_more_evidence")
LABELS = {"approve": "Approve", "reject": "Reject", "request_more_evidence": "Request more evidence"}


